DROP TABLE IF EXISTS `cospay_notify_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `cospay_notify_log` (
  `id` bigint(20) NOT NULL,
  `addtime` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `notify_id` varchar(100) DEFAULT NULL COMMENT '通知ID',
  `pay_order_no` varchar(64) DEFAULT NULL,
  `order_no` varchar(64) DEFAULT NULL,
  `channel` varchar(50) DEFAULT NULL,
  `verify_ok` int(11) DEFAULT '1',
  `payload` longtext,
  `process_status` varchar(50) DEFAULT '成功',
  `error_msg` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_pay_order_no` (`pay_order_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='支付回调日志';
